SELECT SUM(p.Policy_Amount) * 1.0 / COUNT(DISTINCT p.Policy_Identifier) AS average_policy_size
FROM policy_amount p
JOIN premium pr ON p.Policy_Amount_Identifier = pr.Policy_Amount_Identifier;

SELECT DISTINCT p.Policy_Identifier, p.Policy_Number, fc.ClaimNumber
FROM policy p
JOIN fire_claim fc ON p.Policy_Number = fc.PolicyNo;

SELECT pa.*
FROM policy_amount pa
JOIN premium p ON pa.Policy_Amount_Identifier = p.Policy_Amount_Identifier;
